import{f as t,c as e,o as r,a5 as n}from"./chunks/framework.BsEAYNxL.js";const p=JSON.parse('{"title":"AI 编年史 01：上下文 (Context) 的记忆战争","description":"","frontmatter":{"title":"AI 编年史 01：上下文 (Context) 的记忆战争","date":"2026-02-14T00:00:00.000Z","categories":["AI","Tech History"],"tags":["Context Window","RAG","Long Context","Memory","Chronicle"],"ai_role":"writer","reading_stats":{"count":1637,"minutes":5}},"headers":[],"relativePath":"ai-chronicles/02-context.md","filePath":"ai-chronicles/02-context.md","lastUpdated":null}'),s={name:"ai-chronicles/02-context.md"};function o(l,a,i,g,h,m){return r(),e("div",null,[...a[0]||(a[0]=[n('<h2 id="_0-核心工程概念-token-与-embedding" tabindex="-1">0. 核心工程概念：Token 与 Embedding <a class="header-anchor" href="#_0-核心工程概念-token-与-embedding" aria-label="Permalink to &quot;0. 核心工程概念：Token 与 Embedding&quot;">​</a></h2><p>在讨论“记忆”之前，必须先理解 AI 是如何“阅读”的。</p><h3 id="_0-1-token-模型读的不是字" tabindex="-1">0.1 Token：模型读的不是字 <a class="header-anchor" href="#_0-1-token-模型读的不是字" aria-label="Permalink to &quot;0.1 Token：模型读的不是字&quot;">​</a></h3><p><strong>Token</strong> 是分词算法在“压缩效率与表达能力”之间做的取舍结果。它可以是一个字、一个词，甚至是一个字节。</p><ul><li><strong>工程后果</strong>： <ul><li>你的输入长度以 Token 计价（成本/延迟）。</li><li>“边界条件写得太长”会直接把上下文窗口撑爆。</li></ul></li></ul><h3 id="_0-2-embedding-把离散符号变成向量" tabindex="-1">0.2 Embedding：把离散符号变成向量 <a class="header-anchor" href="#_0-2-embedding-把离散符号变成向量" aria-label="Permalink to &quot;0.2 Embedding：把离散符号变成向量&quot;">​</a></h3><p>文字、类目、ID 都是离散符号，计算机没法直接算。<strong>Embedding</strong> 做的事就是：把离散符号映射到一个向量空间里，让“相似性”有机会被学习出来。</p><ul><li><strong>工程直觉</strong>：Embedding 是模型的“词典”，坏 Embedding 会让模型一开始就听不懂你在说什么。</li></ul><h2 id="第一阶段-前-transformer-时代-——-金鱼的记忆-pre-2017" tabindex="-1">第一阶段：前 Transformer 时代 —— 金鱼的记忆 (Pre-2017) <a class="header-anchor" href="#第一阶段-前-transformer-时代-——-金鱼的记忆-pre-2017" aria-label="Permalink to &quot;第一阶段：前 Transformer 时代 —— 金鱼的记忆 (Pre-2017)&quot;">​</a></h2><p>在 Transformer 出现之前，NLP 领域由 RNN (Recurrent Neural Networks) 及其变种 LSTM/GRU 统治。</p><h3 id="_1-1-背景与痛点" tabindex="-1">1.1 背景与痛点 <a class="header-anchor" href="#_1-1-背景与痛点" aria-label="Permalink to &quot;1.1 背景与痛点&quot;">​</a></h3><ul><li><strong>技术背景</strong>：RNN 是一种串行结构，像人类阅读一样，读一个字，更新一次内部状态 (Hidden State)。</li><li><strong>核心痛点</strong>： <ul><li><strong>梯度消失 (Vanishing Gradient)</strong>：随着序列变长，早期的信息在反向传播中逐渐归零。</li><li><strong>无法并行</strong>：必须等上一个字处理完才能处理下一个，训练极慢。</li><li><strong>短视</strong>：RNN 很难记住 100 个词之前的内容，就像金鱼只有 7 秒记忆。</li></ul></li></ul><h3 id="_1-2-关键突破" tabindex="-1">1.2 关键突破 <a class="header-anchor" href="#_1-2-关键突破" aria-label="Permalink to &quot;1.2 关键突破&quot;">​</a></h3><ul><li><strong><a href="https://www.bioinf.jku.at/publications/older/2604.pdf" target="_blank" rel="noreferrer">LSTM (1997)</a></strong>：通过引入“门控机制” (遗忘门、输入门)，强行让模型记住重要信息。虽然缓解了问题，但没根治。</li><li><strong><a href="https://arxiv.org/abs/1409.3215" target="_blank" rel="noreferrer">Seq2Seq + Attention (2014)</a></strong>：Bahdanau Attention 首次提出“注意力机制”，让解码器在生成每个词时，都能回过头看一眼输入序列的所有词。这是 Context 概念的雏形。</li></ul><h2 id="第二阶段-transformer-的诞生-——-固定窗口的枷锁-2017-2020" tabindex="-1">第二阶段：Transformer 的诞生 —— 固定窗口的枷锁 (2017 - 2020) <a class="header-anchor" href="#第二阶段-transformer-的诞生-——-固定窗口的枷锁-2017-2020" aria-label="Permalink to &quot;第二阶段：Transformer 的诞生 —— 固定窗口的枷锁 (2017 - 2020)&quot;">​</a></h2><p>Google 团队发表神作 <em><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">Attention Is All You Need</a></em>，彻底改变了格局。</p><h3 id="_2-1-背景与痛点" tabindex="-1">2.1 背景与痛点 <a class="header-anchor" href="#_2-1-背景与痛点" aria-label="Permalink to &quot;2.1 背景与痛点&quot;">​</a></h3><ul><li><strong>技术背景</strong>：Transformer 抛弃了循环，完全基于 Self-Attention。它能一次性看到所有词之间的关系。</li><li><strong>核心痛点</strong>： <ul><li><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><msup><mi>N</mi><mn>2</mn></msup><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(N^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.10903em;">N</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 复杂度</strong>：Attention 矩阵的大小是序列长度的平方。如果序列长 2 倍，计算量增加 4 倍。这导致显存和算力无法承受长文本。</li><li><strong>位置编码限制</strong>：早期的绝对位置编码 (Absolute Positional Encoding) 训练时定死了最大长度 (如 512 或 1024)，推理时无法超越。</li></ul></li></ul><h3 id="_2-2-关键论文" tabindex="-1">2.2 关键论文 <a class="header-anchor" href="#_2-2-关键论文" aria-label="Permalink to &quot;2.2 关键论文&quot;">​</a></h3><ul><li><strong><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">Attention Is All You Need (2017)</a></strong>：定义了标准 Transformer 架构，Context Window 通常限制在 512 tokens (BERT) 或 1024 tokens (GPT-1)。</li></ul><h2 id="第三阶段-gpt-3-与工程-hack-——-带着镣铐跳舞-2020-2023" tabindex="-1">第三阶段：GPT-3 与工程 Hack —— 带着镣铐跳舞 (2020 - 2023) <a class="header-anchor" href="#第三阶段-gpt-3-与工程-hack-——-带着镣铐跳舞-2020-2023" aria-label="Permalink to &quot;第三阶段：GPT-3 与工程 Hack —— 带着镣铐跳舞 (2020 - 2023)&quot;">​</a></h2><p>OpenAI 发布 <a href="https://arxiv.org/abs/2005.14165" target="_blank" rel="noreferrer">GPT-3</a>，虽然参数量巨大 (175B)，但 Context Window 依然只有 2048 tokens。</p><h3 id="_3-1-背景与痛点" tabindex="-1">3.1 背景与痛点 <a class="header-anchor" href="#_3-1-背景与痛点" aria-label="Permalink to &quot;3.1 背景与痛点&quot;">​</a></h3><ul><li><strong>业务问题</strong>：2048 tokens 大约只有 1500 个汉字。多轮对话没几句就超了，长文档根本读不完。</li><li><strong>工程范式 (Hack 方案)</strong>：既然模型不行，工程师就开始整活。 <ul><li><strong>滑动窗口 (Sliding Window)</strong>：只把最近的 N 轮对话塞进 Prompt，前面的直接截断。</li><li><strong>摘要缓冲 (Summary Memory)</strong>：让 LLM 定期总结之前的对话：“我们之前聊了 A、B、C...”，然后把摘要塞进 System Prompt。</li><li><strong>Map-Reduce</strong>：处理长文档时，把文档切成 10 段，分别总结，最后再总结“总结的总结”。</li></ul></li></ul><h3 id="_3-2-代表产品-库" tabindex="-1">3.2 代表产品/库 <a class="header-anchor" href="#_3-2-代表产品-库" aria-label="Permalink to &quot;3.2 代表产品/库&quot;">​</a></h3><ul><li><strong>LangChain</strong>：依靠封装各种 Memory 模式 (Buffer, Summary, KnowledgeGraph) 起家，本质上是在帮模型“外挂”记忆管理。</li></ul><h2 id="第四阶段-rag-与向量数据库-——-外挂海马体-2023" tabindex="-1">第四阶段：RAG 与向量数据库 —— 外挂海马体 (2023) <a class="header-anchor" href="#第四阶段-rag-与向量数据库-——-外挂海马体-2023" aria-label="Permalink to &quot;第四阶段：RAG 与向量数据库 —— 外挂海马体 (2023)&quot;">​</a></h2><p>随着 ChatGPT 的爆火，企业知识库需求井喷。既然 Prompt 塞不下，那就“按需加载”。</p><h3 id="_4-1-背景与痛点" tabindex="-1">4.1 背景与痛点 <a class="header-anchor" href="#_4-1-背景与痛点" aria-label="Permalink to &quot;4.1 背景与痛点&quot;">​</a></h3><ul><li><strong>业务问题</strong>：模型有幻觉 (Hallucination)，且知识停留在训练截止日期。企业有大量私有 PDF/Wiki 需要问答。</li><li><strong>核心痛点</strong>：Fine-tuning 太贵且慢，无法实时更新知识。</li></ul><h3 id="_4-2-解决方案-rag-retrieval-augmented-generation" tabindex="-1">4.2 解决方案：RAG (Retrieval-Augmented Generation) <a class="header-anchor" href="#_4-2-解决方案-rag-retrieval-augmented-generation" aria-label="Permalink to &quot;4.2 解决方案：RAG (Retrieval-Augmented Generation)&quot;">​</a></h3><ul><li><strong>原理</strong>： <ol><li><strong>Indexing</strong>：把海量文档切片 (Chunking)，用 Embedding 模型转成向量，存入向量数据库。</li><li><strong>Retrieval</strong>：用户提问时，搜出最相关的 Top-K 个片段。</li><li><strong>Generation</strong>：把片段拼接到 Prompt 里：“请根据以下资料回答...”。</li></ol></li><li><strong>延伸问题</strong>： <ul><li><strong>切片破碎</strong>：切片可能把一句话切断，导致上下文丢失。</li><li><strong>召回不准</strong>：关键词匹配不一定代表语义匹配。</li></ul></li></ul><h3 id="_4-3-关键技术与产品" tabindex="-1">4.3 关键技术与产品 <a class="header-anchor" href="#_4-3-关键技术与产品" aria-label="Permalink to &quot;4.3 关键技术与产品&quot;">​</a></h3><ul><li><strong>Vector DBs</strong>：Pinecone, Milvus, Chroma, Weaviate。</li><li><strong>Embedding Models</strong>：OpenAI text-embedding-ada-002, BGE (BAAI)。</li></ul><h2 id="第五阶段-long-context-大爆发-——-暴力美学-2023-下半年-2024" tabindex="-1">第五阶段：Long Context 大爆发 —— 暴力美学 (2023 下半年 - 2024) <a class="header-anchor" href="#第五阶段-long-context-大爆发-——-暴力美学-2023-下半年-2024" aria-label="Permalink to &quot;第五阶段：Long Context 大爆发 —— 暴力美学 (2023 下半年 - 2024)&quot;">​</a></h2><p>模型架构师们终于出手了，通过算法优化打破了 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>O</mi><mo stretchy="false">(</mo><msup><mi>N</mi><mn>2</mn></msup><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">O(N^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.10903em;">N</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 的魔咒。</p><h3 id="_5-1-背景与痛点" tabindex="-1">5.1 背景与痛点 <a class="header-anchor" href="#_5-1-背景与痛点" aria-label="Permalink to &quot;5.1 背景与痛点&quot;">​</a></h3><ul><li><strong>业务问题</strong>：RAG 只能回答“局部”问题，无法回答“全文总结”或“跨段落推理”的问题（大海捞针问题）。</li><li><strong>技术突破</strong>： <ul><li><strong><a href="https://arxiv.org/abs/2205.14135" target="_blank" rel="noreferrer">FlashAttention (Dao et al.)</a></strong>：通过显存 IO 优化，让 Attention 计算速度提升数倍，显存占用大幅降低。</li><li><strong><a href="https://arxiv.org/abs/2104.09864" target="_blank" rel="noreferrer">RoPE (Rotary Positional Embedding)</a></strong>：旋转位置编码，支持外推 (Extrapolation)，让模型能处理比训练时更长的序列。</li><li><strong><a href="https://arxiv.org/abs/2108.12409" target="_blank" rel="noreferrer">ALiBi</a></strong>：另一种位置编码，天然支持长文本。</li></ul></li></ul><h3 id="_5-2-代表产品" tabindex="-1">5.2 代表产品 <a class="header-anchor" href="#_5-2-代表产品" aria-label="Permalink to &quot;5.2 代表产品&quot;">​</a></h3><ul><li><strong><a href="https://www.anthropic.com/news/claude-2" target="_blank" rel="noreferrer">Claude 2</a> (100k)</strong> -&gt; <strong>Claude 3 (200k)</strong>：以“大海捞针”测试全绿著称。</li><li><strong><a href="https://moonshot.cn/" target="_blank" rel="noreferrer">Kimi</a> (Moonshot AI)</strong>：支持 20万字，后续通过 Cache 机制支持 200万字。</li><li><strong><a href="https://blog.google/technology/ai/google-gemini-next-generation-model-february-2024/" target="_blank" rel="noreferrer">Gemini 1.5 Pro</a> (Google)</strong>：利用 Ring Attention 架构，支持 <strong>100万 ~ 1000万 Tokens</strong>。这是一个质变，可以直接把 1 小时的视频、几十本代码库塞进 Context。</li></ul><h2 id="第六阶段-无限未来-——-结构化与系统-2-future" tabindex="-1">第六阶段：无限未来 —— 结构化与系统 2 (Future) <a class="header-anchor" href="#第六阶段-无限未来-——-结构化与系统-2-future" aria-label="Permalink to &quot;第六阶段：无限未来 —— 结构化与系统 2 (Future)&quot;">​</a></h2><p>当 Context 足够长时，注意力分散 (Lost in the Middle) 成了新问题。未来的方向不是单纯堆长度，而是“结构化”。</p><h3 id="_6-1-新的挑战" tabindex="-1">6.1 新的挑战 <a class="header-anchor" href="#_6-1-新的挑战" aria-label="Permalink to &quot;6.1 新的挑战&quot;">​</a></h3><ul><li><strong>注意力稀释</strong>：给模型 100 本书，它可能反而变笨了，找不到重点。</li><li><strong>成本问题</strong>：输入 1M tokens 的费用极其昂贵。</li></ul><h3 id="_6-2-演进方向" tabindex="-1">6.2 演进方向 <a class="header-anchor" href="#_6-2-演进方向" aria-label="Permalink to &quot;6.2 演进方向&quot;">​</a></h3><ul><li><strong><a href="https://www.microsoft.com/en-us/research/blog/graphrag-unlocking-llm-discovery-on-narrative-private-data/" target="_blank" rel="noreferrer">GraphRAG</a></strong>：微软提出的概念。先用 LLM 把文档提取成<strong>知识图谱 (Knowledge Graph)</strong>，查询时在图上游走。这解决了 RAG “只见树木不见森林”的问题。</li><li><strong><a href="https://arxiv.org/abs/2310.08560" target="_blank" rel="noreferrer">MemGPT</a> / System 2</strong>：模拟操作系统的内存管理。 <ul><li><strong>RAM (Context)</strong>：放当前最关注的信息。</li><li><strong>Disk (VectorDB)</strong>：放冷数据。</li><li><strong>Swap 机制</strong>：让 Agent 自己决定什么时候把信息写入磁盘，什么时候读出来。</li></ul></li></ul><h3 id="_6-3-总结" tabindex="-1">6.3 总结 <a class="header-anchor" href="#_6-3-总结" aria-label="Permalink to &quot;6.3 总结&quot;">​</a></h3><p>从“金鱼记忆”到“外挂硬盘”，再到“超大内存”，AI 上下文的发展史，就是一部<strong>算力与算法协同进化</strong>的历史。</p>',48)])])}const c=t(s,[["render",o]]);export{p as __pageData,c as default};
